// UpdateSavedAnimationsFilter filters UpdateSavedAnimations updates.
// The list of saved animations was updated
type UpdateSavedAnimationsFilter func(u *UpdateSavedAnimations) bool

// UpdateSavedMessagesTagsFilter filters UpdateSavedMessagesTags updates.
// Tags used in Saved Messages or a Saved Messages topic have changed
type UpdateSavedMessagesTagsFilter func(u *UpdateSavedMessagesTags) bool

// UpdateSavedMessagesTopicFilter filters UpdateSavedMessagesTopic updates.
